import os
import json
from datetime import datetime, timezone

# Check raw directory for recent unscored items
raw_dir = os.path.join(os.path.expanduser('~'), '.hermes', 'mempalace', 'raw')
unscored = []
scored_recent = []

now = datetime.now(timezone.utc)
for fname in os.listdir(raw_dir):
    if fname.endswith('.json'):
        path = os.path.join(raw_dir, fname)
        try:
            with open(path) as f:
                data = json.load(f)
            if 'score' not in data:
                unscored.append(fname)
            else:
                # Check if scored recently (within last hour)
                scored_at = data.get('scored_at')
                if scored_at:
                    try:
                        scored_time = datetime.fromisoformat(scored_at.replace('Z', '+00:00'))
                        if (now - scored_time).total_seconds() < 3600:
                            scored_recent.append(fname)
                    except:
                        pass
        except:
            pass

print(f'Total raw files: {len([f for f in os.listdir(raw_dir) if f.endswith(\".json\")])}')
print(f'Unscored files: {len(unscored)}')
print(f'Recently scored (last hour): {len(scored_recent)}')
if unscored:
    print(f'First few unscored: {unscored[:5]}')
""}

